import copy, re, zipfile, os
from difflib import SequenceMatcher
from lxml import etree
W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XS = "{http://www.w3.org/XML/1998/namespace}space"
def q(t): return "{%s}%s" % (W, t)
AUTHOR = "Ceritas Therapeutics (QA/Legal)"
DATE = "2025-04-21T09:00:00Z"
def A(s): return s.replace("’", chr(39))

class Doc:
    def __init__(self, path):
        self.path = path
        self.tree = etree.parse(path)
        self.root = self.tree.getroot()
        self.body = self.root.find(q("body"))
        self.rid = 5000
        self.log = []
    def nid(self):
        self.rid += 1
        return str(self.rid)
    def mark(self, tag):
        e = etree.Element(q(tag))
        e.set(q("id"), self.nid()); e.set(q("author"), AUTHOR); e.set(q("date"), DATE)
        return e
    def paras(self):
        return list(self.body.iter(q("p")))
    @staticmethod
    def ptext(p):
        return "".join(t.text or "" for t in p.iter(q("t")))
    def find(self, key, n=None):
        key = A(key)
        m = [p for p in self.paras() if key in self.ptext(p)]
        if not m:
            raise SystemExit("NOT FOUND: " + key)
        if n is None:
            if len(m) > 1:
                raise SystemExit("AMBIGUOUS (%d): %s" % (len(m), key))
            return m[0]
        return m[n]
    # ---- run helpers
    def _run(self, text, rpr, deleted=False):
        r = etree.Element(q("r"))
        if rpr is not None:
            r.append(copy.deepcopy(rpr))
        t = etree.SubElement(r, q("delText" if deleted else "t"))
        t.set(XS, "preserve")
        t.text = text
        return r
    def _chars(self, p):
        runs = [c for c in p if c.tag == q("r")]
        chars = []
        for r in runs:
            rpr = r.find(q("rPr"))
            for c in r:
                if c.tag == q("rPr"):
                    continue
                if c.tag == q("t"):
                    for ch in (c.text or ""):
                        chars.append((ch, rpr))
                else:
                    raise SystemExit("unsupported run child %s in %s" % (c.tag, self.ptext(p)[:60]))
        return runs, chars
    def _segments(self, chars, i, j):
        out = []
        k = i
        while k < j:
            rpr = chars[k][1]
            s = k
            while k < j and chars[k][1] is rpr:
                k += 1
            out.append(("".join(c[0] for c in chars[s:k]), rpr))
        return out
    def edit(self, p, new_text, whole=False):
        new_text = A(new_text)
        runs, chars = self._chars(p)
        old = "".join(c[0] for c in chars)
        if old == new_text:
            return
        tok = lambda s: re.findall(r"\w+|\s+|[^\w\s]", s)
        a, b = tok(old), tok(new_text)
        if whole:
            ops = [("delete", 0, len(a), 0, 0), ("insert", len(a), len(a), 0, len(b))]
        else:
            ops = SequenceMatcher(None, a, b, autojunk=False).get_opcodes()
        # cumulative char offsets
        aoff = [0]
        for t in a: aoff.append(aoff[-1] + len(t))
        new_elems = []
        for tag, i1, i2, j1, j2 in ops:
            ci, cj = aoff[i1], aoff[i2]
            if tag == "equal":
                for txt, rpr in self._segments(chars, ci, cj):
                    new_elems.append(self._run(txt, rpr))
                continue
            if tag in ("delete", "replace") and cj > ci:
                d = self.mark("del")
                for txt, rpr in self._segments(chars, ci, cj):
                    d.append(self._run(txt, rpr, deleted=True))
                new_elems.append(d)
            if tag in ("insert", "replace") and j2 > j1:
                txt = "".join(b[j1:j2])
                if not txt:
                    continue
                if ci > 0:
                    rpr = chars[ci - 1][1]
                elif chars:
                    rpr = chars[0][1]
                else:
                    rpr = None
                # avoid inheriting bold from a bold number prefix when inserting body text
                ins = self.mark("ins")
                ins.append(self._run(txt, rpr))
                new_elems.append(ins)
        idx = list(p).index(runs[0]) if runs else len(p)
        for r in runs:
            p.remove(r)
        for e in reversed(new_elems):
            p.insert(idx, e)
        self.log.append(("edit", old[:70]))
    def rep(self, key, old, new, n=None):
        p = self.find(key, n)
        cur = self.ptext(p)
        old, new = A(old), A(new)
        if cur.count(old) != 1:
            raise SystemExit("rep: old fragment count=%d in para: %s || %s" % (cur.count(old), old, cur[:80]))
        self.edit(p, cur.replace(old, new))
        return p
    def whole(self, key, new, n=None):
        p = self.find(key, n)
        self.edit(p, new, whole=True)
        return p
    def delete(self, key, n=None):
        p = self.find(key, n) if isinstance(key, str) else key
        for r in [c for c in p if c.tag == q("r")]:
            for t in r.findall(q("t")):
                t.tag = q("delText")
            d = self.mark("del")
            r.addprevious(d)
            d.append(r)
        self._mark_para(p, "del")
        self.log.append(("delete", self.ptext(p)[:60]))
        return p
    def _mark_para(self, p, kind):
        ppr = p.find(q("pPr"))
        if ppr is None:
            ppr = etree.Element(q("pPr")); p.insert(0, ppr)
        rpr = ppr.find(q("rPr"))
        if rpr is None:
            rpr = etree.Element(q("rPr"))
            sp = ppr.find(q("sectPr"))
            if sp is not None: sp.addprevious(rpr)
            else: ppr.append(rpr)
        rpr.append(self.mark(kind))
    def new_para(self, template, segments):
        p = etree.Element(q("p"))
        tppr = template.find(q("pPr"))
        if tppr is not None:
            ppr = copy.deepcopy(tppr)
            for x in ppr.findall(q("sectPr")) + ppr.findall(q("rPr")) + ppr.findall(q("pPrChange")):
                ppr.remove(x)
            p.append(ppr)
        self._mark_para(p, "ins")
        truns = [c for c in template if c.tag == q("r") and c.find(q("rPr")) is not None]
        base = copy.deepcopy(truns[-1].find(q("rPr"))) if truns else None
        keep = copy.deepcopy(truns[0].find(q("rPr"))) if truns else None
        ins = self.mark("ins")
        for text, style in segments:
            text = A(text)
            if style == "keep":
                rpr = copy.deepcopy(keep)
            else:
                rpr = copy.deepcopy(base) if base is not None else etree.Element(q("rPr"))
                for tg in ("b", "i", "u"):
                    for x in rpr.findall(q(tg)): rpr.remove(x)
                order = ["rStyle","rFonts","b","bCs","i","iCs","caps","smallCaps","strike","dstrike","outline","shadow","emboss","imprint","noProof","snapToGrid","vanish","webHidden","color","spacing","w","kern","position","sz","szCs","highlight","u"]
                def add(tg, val=None):
                    e = etree.Element(q(tg))
                    if val: e.set(q("val"), val)
                    pos = order.index(tg)
                    for idx, ch in enumerate(list(rpr)):
                        nm = etree.QName(ch).localname
                        if nm in order and order.index(nm) > pos:
                            ch.addprevious(e); return
                    rpr.append(e)
                if "b" in style: add("b")
                if "i" in style: add("i")
                if "u" in style: add("u", "single")
            ins.append(self._run(text, rpr))
        p.append(ins)
        return p
    def after(self, anchor, template, items):
        if isinstance(anchor, str): anchor = self.find(anchor)
        if isinstance(template, str): template = self.T[template]
        cur = anchor
        for segs in items:
            if isinstance(segs, str): segs = [(segs, "n")]
            if isinstance(segs, tuple) and len(segs) == 3:
                tmpl = self.T[segs[0]]; segs2 = segs[1]
                if isinstance(segs2, str): segs2 = [(segs2, segs[2])]
                np_ = self.new_para(tmpl, segs2)
            else:
                np_ = self.new_para(template, segs)
            cur.addnext(np_)
            cur = np_
        self.log.append(("insert", len(items)))
        return cur
    def before(self, anchor, template, items):
        if isinstance(anchor, str): anchor = self.find(anchor)
        prev = anchor.getprevious()
        # insert sequentially before anchor
        cur = None
        for segs in items:
            if isinstance(segs, str): segs = [(segs, "n")]
            if isinstance(segs, tuple) and len(segs) == 3:
                tmpl = self.T[segs[0]]; segs2 = segs[1]
                if isinstance(segs2, str): segs2 = [(segs2, segs[2])]
                np_ = self.new_para(tmpl, segs2)
            else:
                np_ = self.new_para(self.T[template] if isinstance(template, str) else template, segs)
            anchor.addprevious(np_)
        return anchor
    def save(self, path):
        self.tree.write(path, xml_declaration=True, encoding="UTF-8", standalone=True)
