def _chars2(self, p):
    kids = [c for c in p if c.tag != q("pPr")]
    chars, anchors = [], []
    for c in kids:
        if c.tag == q("r"):
            rpr = c.find(q("rPr"))
            for x in c:
                if x.tag == q("rPr"): continue
                if x.tag != q("t"): raise SystemExit("unsupported child " + x.tag)
                for ch in (x.text or ""): chars.append((ch, rpr, "p"))
        elif c.tag == q("ins"):
            for r in c.findall(q("r")):
                rpr = r.find(q("rPr"))
                for x in r.findall(q("t")):
                    for ch in (x.text or ""): chars.append((ch, rpr, "i"))
        elif c.tag == q("del"):
            anchors.append((len(chars), c))
        else:
            raise SystemExit("unsupported para child " + c.tag)
    return kids, chars, anchors

def _segs2(chars, i, j):
    out = []; k = i
    while k < j:
        rpr, kind = chars[k][1], chars[k][2]; s = k
        while k < j and chars[k][1] is rpr and chars[k][2] == kind: k += 1
        out.append(("".join(c[0] for c in chars[s:k]), rpr, kind, s, k))
    return out

def _edit2(self, p, new_text, whole=False):
    new_text = A(new_text)
    kids, chars, anchors = self._chars2(p)
    old = "".join(c[0] for c in chars)
    if old == new_text: return
    tok = lambda s: re.findall(r"\w+|\s+|[^\w\s]", s)
    a, b = tok(old), tok(new_text)
    if whole:
        ops = [("delete", 0, len(a), 0, 0), ("insert", len(a), len(a), 0, len(b))]
    else:
        ops = SequenceMatcher(None, a, b, autojunk=False).get_opcodes()
    aoff = [0]
    for t in a: aoff.append(aoff[-1] + len(t))
    out = []
    pend = list(anchors)
    def flush(upto):
        while pend and pend[0][0] <= upto:
            out.append(pend.pop(0)[1])
    def emit_eq(txt, rpr, kind):
        r = self._run(txt, rpr)
        if kind == "i":
            w = self.mark("ins"); w.append(r); out.append(w)
        else:
            out.append(r)
    for tag, i1, i2, j1, j2 in ops:
        ci, cj = aoff[i1], aoff[i2]
        if tag == "equal":
            for txt, rpr, kind, s, e in _segs2(chars, ci, cj):
                flush(s)
                emit_eq(txt, rpr, kind)
            continue
        if tag in ("delete", "replace") and cj > ci:
            for txt, rpr, kind, s, e in _segs2(chars, ci, cj):
                flush(s)
                if kind == "p":
                    dl = self.mark("del"); dl.append(self._run(txt, rpr, deleted=True)); out.append(dl)
                # deleting text that was itself an insertion: simply drop it
        if tag in ("insert", "replace") and j2 > j1:
            txt = "".join(b[j1:j2])
            flush(ci)
            rpr = chars[ci - 1][1] if ci > 0 else (chars[0][1] if chars else None)
            w = self.mark("ins"); w.append(self._run(txt, rpr)); out.append(w)
    flush(10**9)
    ppr = p.find(q("pPr"))
    for c in kids: p.remove(c)
    for e in out: p.append(e)
    self.log.append(("edit", old[:70]))

